  /// # Errors
  ///
  /// [`CoreError::InvalidId`] for a malformed room ID, otherwise as the server answers.
  Future<void> setRoomNotificationMode({
    required String roomId,
    RoomNotificationMode? mode,
  });

  /// Lists the room in the server's room directory, or takes it out.
  ///
  /// # Errors
  ///
  /// As [`Self::set_room_name`]; a server that lets only its admins publish refuses.
  Future<void> setRoomPublished({
    required String roomId,
    required bool published,
  });

  /// Puts a room in the section with `tag` (`m.favourite`, `m.lowpriority` or a section the
  /// user made), or with `None` in its default section (People or Rooms). A room is in one
  /// section at a time; the one it was in is left.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`] for a malformed room ID or a tag that isn't a section's,
  /// [`CoreError::RoomNotFound`], otherwise as the server answers.
  Future<void> setRoomSection({required String roomId, String? tag});

  /// Gives the room the topic `topic`; an empty one takes the topic away.
  ///
  /// # Errors
  ///
  /// As [`Self::set_room_name`].
  Future<void> setRoomTopic({required String roomId, required String topic});

  /// Signs the account's devices `device_ids` out; this one logs out with
  /// [`Self::logout`] instead. The server asks for the account's password: without
  /// `password` this fails with [`CoreError::PasswordNeeded`], so the app can ask for it
  /// and call again.
  ///
  /// # Errors
  ///
  /// [`CoreError::PasswordNeeded`], [`CoreError::WrongPassword`], [`CoreError::Internal`]
  /// if `device_ids` holds this device, otherwise as the server answers.
  Future<void> signOutDevices({
    required List<String> deviceIds,
    String? password,
  });

  /// Starts syncing. Calling it while syncing is harmless; while offline it retries at once.
  Future<void> startSync();

  /// Stops syncing, e.g. when the app goes to the background.
  Future<void> stopSync();

  /// Sends the account's [`Self::devices`] now, then whenever they may have changed: a
  /// device signed in or out, renamed, or verified. A failed fetch sends nothing; the next
  /// change tries again.
  Stream<List<DeviceInfo>> subscribeDevices();

  /// Sends the current [`EncryptionStatus`], then every change.
  Stream<EncryptionStatus> subscribeEncryptionStatus();

  /// Sends [`Session::ignored_users`] now, then again whenever the list changes, here or on
  /// another device.
  Stream<List<String>> subscribeIgnoredUsers();

  /// Sends every ring addressed to the user from now on, and when each one stops. A ring
  /// counts while it is fresh (MSC4075 lifetime), the call it is about is going on and the
  /// user is not in it yet.
  Stream<IncomingCallUpdate> subscribeIncomingCalls();

  /// Sends the account's notification settings, then the settings after every change, made
  /// here or on another device.
  Stream<NotificationSettingsState> subscribeNotificationSettings();

  /// Sends every message that should show as an OS notification from now on: it notifies
  /// by the push rules (decrypted first if it is encrypted), and it isn't the user's own.
  Stream<NotificationItem> subscribeNotifications();

  /// Sends how far a running [`Self::enable_recovery`] is, from now on.
  Stream<RecoveryProgress> subscribeRecoveryProgress();

  /// Sends the room's call now, then after every change: someone joining, leaving, or their
  /// membership running out.
  ///
  /// # Errors
  ///
  /// As [`Self::room_call`].
  Stream<RoomCall> subscribeRoomCall({required String roomId});

  /// Sends the room's [`Self::room_settings`] now, then after every change, made here or
  /// elsewhere (they arrive with the sync), power levels included.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`] or [`CoreError::RoomNotFound`].
  Stream<RoomSettings> subscribeRoomSettings({required String roomId});

  /// Sends the room list as batches of diffs. The first batch is a `Reset` with the whole
  /// list.
  ///
  /// # Errors
  ///
  /// If the SDK's room list can't be set up.
  Stream<List<RoomListDiff>> subscribeRooms();

  /// Sends the section settings and the tags of every room, then every change to either.
  Stream<SectionsUpdate> subscribeSections();

  /// Sends every [`SessionChange`].
  Stream<SessionChange> subscribeSessionChanges();

  /// Sends the current [`SyncState`], then every change.
  Stream<SyncState> subscribeSyncState();

  /// Sends who is typing, for every room, whenever it changes.
  Stream<RoomTyping> subscribeTyping();

  /// Sends every verification request that arrives from another device of the user.
  Stream<VerificationRequestInfo> subscribeVerificationRequests();

  /// Sends the current [`VerificationStatus`], then every change.
  Stream<VerificationStatus> subscribeVerificationStatus();

  /// The threads of a room the user is in. Nothing is loaded until
  /// [`ThreadList::paginate`].
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`] or [`CoreError::RoomNotFound`].
  Future<ThreadList> threadList({required String roomId});

  /// Opens the thread that starts at the event `root_event_id`: its first message, then the
  /// replies. Whatever is sent through it goes into the thread.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`], [`CoreError::RoomNotFound`], or if the thread can't be loaded.
  Future<Timeline> threadTimeline({
    required String roomId,
    required String rootEventId,
  });

  /// A square thumbnail of the picture at `mxc_uri`, about `size` pixels wide, as encoded
  /// image bytes.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`] for a malformed `mxc://` URI, otherwise as the server answers.
  Future<Uint8List> thumbnail({required String mxcUri, required int size});

  /// Opens the timeline of a room the user is in. Replies in threads stay in their threads;
  /// a thread's first message carries [`EventInfo::thread`].
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`], or [`CoreError::RoomNotFound`] for a room the session doesn't
  /// know.
  Future<Timeline> timeline({required String roomId});

  /// Lifts `user_id`'s ban; they can join again when invited or the room is public.
  ///
  /// # Errors
  ///
  /// As [`Session::set_power_level`].
  Future<void> unbanMember({required String roomId, required String userId});

  /// Stops ignoring `user_id`; their messages show again.
  ///
  /// # Errors
  ///
  /// As [`Session::ignore_user`].
  Future<void> unignoreUser({required String userId});

  /// The logged-in user's Matrix ID.
  String userId();

  /// `user_id`'s profile: their name and picture in the room `room_id` if given and they are
  /// a member, else as their server tells.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`]. A profile the server won't tell (e.g. nobody shares a room
  /// with them) comes without name and picture, not as an error.
  Future<UserProfile> userProfile({required String userId, String? roomId});

  /// Opens a request that arrived through [`Self::subscribe_verification_requests`].
  ///
  /// # Errors
  ///
  /// [`CoreError::Internal`] if the request is unknown, e.g. already cancelled.
  Future<Verification> verification({required String flowId});

  /// Asks the account's device `device_id` to verify with this one, by emoji. The other
  /// device shows the request; the [`Verification`] follows it as for this device's own.
  ///
  /// # Errors
  ///
  /// [`CoreError::Internal`] if this device doesn't have the other's keys (yet), otherwise
  /// as the server answers.
  Future<Verification> verifyDevice({required String deviceId});

  /// Asks `user_id` to verify with the user by emoji, in their direct chat (made if there is
  /// none); this side starts the emoji once they accept, as with the user's own devices.
  ///
  /// # Errors
  ///
  /// [`CoreError::InvalidId`]; [`CoreError::Internal`] if they have no cross-signing identity
  /// or the chat can't be made; otherwise as the server answers.
  Future<Verification> verifyUser({required String userId});
}

@freezed
sealed class SessionChange with _$SessionChange {
  const SessionChange._();

  /// The server rejected the access token. With `soft_logout` the user may log in again on
  /// the same device and keep its keys.
  const factory SessionChange.unknownToken({required bool softLogout}) =
      SessionChange_UnknownToken;

  /// The tokens were refreshed; the app should store [`Session::session_data`] again.
  const factory SessionChange.tokensRefreshed() = SessionChange_TokensRefreshed;
}

/// What the app keeps in secure storage to restore a session without logging in again.
class SessionData {
  final String homeserverUrl;
  final String userId;
  final String deviceId;
  final String accessToken;

  const SessionData({
    required this.homeserverUrl,
    required this.userId,
    required this.deviceId,
    required this.accessToken,
  });

  @override
  int get hashCode =>
      homeserverUrl.hashCode ^
      userId.hashCode ^
      deviceId.hashCode ^
      accessToken.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SessionData &&
          runtimeType == other.runtimeType &&
          homeserverUrl == other.homeserverUrl &&
          userId == other.userId &&
          deviceId == other.deviceId &&
          accessToken == other.accessToken;
}
